import sys
from collections import defaultdict

def find_cycle(graph, start, visited, path, is_floor):
    if len(path) > 2 and start in graph[path[-1]] and path[0] == start:
        return True
    for neighbor in graph[start]:
        if (not is_floor or neighbor not in path) and not visited[neighbor]:
            visited[neighbor] = True
            if find_cycle(graph, neighbor, visited, path + [neighbor], is_floor):
                return True
            visited[neighbor] = False
    return False

def main():
    import sys
    input = sys.stdin.read().split()
    K = int(input[0])
    needles = []
    for i in range(K):
        x1, y1, z1, x2, y2, z2 = map(int, input[1 + 6 * i:7 + 6 * i])
        needles.append(((x1, y1, z1), (x2, y2, z2)))

    true_graph = defaultdict(list)
    floor_graph = defaultdict(list)
    true_visited = defaultdict(bool)
    floor_visited = defaultdict(bool)

    for (x1, y1, z1), (x2, y2,z2) in needles:
        true_graph[(x1, y1, z1)].append((x2, y2, z2))
        true_graph[(x2, y2, z2)].append((x1, y1, z1))
        floor_graph[(x1, y1)].append((x2, y2))
        floor_graph[(x2, y2)].append((x1, y1))

    true_cycle = False
    floor_cycle = False

    for node in true_graph:
        if not true_visited[node]:
            true_visited[node] = True
            if find_cycle(true_graph, node, true_visited, [node], False):
                true_cycle = True
                break

    for node in floor_graph:
        if not floor_visited[node]:
            floor_visited[node] = True
            if find_cycle(floor_graph, node, floor_visited, [node], True):
                floor_cycle = True
                break

    print("True closed chains" if true_cycle else "No true closed chains")
    print("Floor closed chains" if floor_cycle else "No floor closed chains")

main()
